import { 
  MeshBasicNodeMaterial, 
  PlaneGeometry,
  Mesh,
  Group
} from 'three/webgpu';
import { uv, vec2, vec4, texture } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group: THREEGroup, Mesh: THREEMesh, Color } = ctx.THREE;

  // 1. Setup root container
  const rootGroup = new THREEGroup();
  rootGroup.name = "features-title-root";

  // Keep track of resources to clean up
  const tweens = [];
  const textures = [];

  // 2. Palette & Config
  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {
    ink: "#16161d",
    paper: "#e8ecf2",
    accent: "#ff2a38",
    surface: "#0b0b10"
  };

  // 3. Stage backdrop / gradient card surface (engineered gradient + subtle grain)
  // Sized to atlas region aspect ratio (512, 320) -> aspect 1.6
  const width = 4.0;
  const height = width / 1.6;
  const geometry = new PlaneGeometry(width, height);

  // Custom node material to blend engineered gradient & grain texture map
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;
  material.depthWrite = false;

  // Load the ceramic grain texture if provided
  const imgUrl = config.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png';
  ctx.textureLoader.loadTexture(imgUrl).then((tex) => {
    tex.wrapS = ctx.THREE.RepeatWrapping;
    tex.wrapT = ctx.THREE.RepeatWrapping;
    textures.push(tex);

    // Coordinate space and UV logic mapping atlas coordinates to standard coords
    // Atlas Source rect: 0, 0, 512, 320. If we treat it as standard normalized UVs:
    const baseUV = uv();

    // TSL Shader node setup: Engineered gradient (surface to ink corner) mixed with grain
    const colorSurface = vec4(new Color(colors.surface).convertSRGBToLinear(), 1.0);
    const colorInk = vec4(new Color(colors.ink).convertSRGBToLinear(), 1.0);

    // Simple vertical gradient factor
    const gradFactor = baseUV.y;
    const gradColor = colorSurface.mix(colorInk, gradFactor);

    // Sample texture for ceramic grain
    const grainTexSample = texture(tex, baseUV.mul(vec2(1.5, 1.5)));

    // Smooth grain blending (modulating lightness slightly)
    const finalColor = gradColor.mul(grainTexSample.r.mul(0.15).add(0.85));

    material.colorNode = finalColor;
    material.needsUpdate = true;
  });

  const backdropMesh = new Mesh(geometry, material);
  rootGroup.add(backdropMesh);

  // 4. Render Text via Atlas API
  // Text content "Features" (headline, 96px 400 equivalent -> high visual contrast display)
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textStr = items[0]?.text ?? "Features";

  const headlineText = ctx.fontAtlas.createText(textStr, {
    fontSize: 0.38, // 0.34 - 0.62 range, elegant size centered on card
    color: colors.paper,
    align: 'center'
  });

  // Position headline slightly forward to prevent z-fighting and align nicely
  headlineText.position.set(0, -0.05, 0.05);
  rootGroup.add(headlineText);

  // Red accent indicator bar underneath "Features" to anchor the machined system look
  const accentGeo = new PlaneGeometry(0.35, 0.02);
  const accentMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent).convertSRGBToLinear()
  });
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(0, -0.4, 0.05);
  rootGroup.add(accentMesh);

  // 5. Billboard / Sprite orientation toward the camera (optional slight hover sway for richness)
  // Ensure we adapt to standard Sprite behavior constraints if specified, or stable billboard setup
  rootGroup.quaternion.identity();

  // Subtle entrance animation (weighted-settle pattern)
  rootGroup.scale.set(0.01, 0.01, 0.01);
  const scaleTween = gsap.to(rootGroup.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: "power4.out"
  });
  tweens.push(scaleTween);

  // Subtle idle breathing motion representing pristine precision
  const idleTween = gsap.to(rootGroup.position, {
    y: "+=0.03",
    duration: 3.5,
    repeat: -1,
    yoyo: true,
    ease: "sine.inOut"
  });
  tweens.push(idleTween);

  // Cleanup handler
  rootGroup.userData = {
    cleanup() {
      tweens.forEach(t => t.kill());
      textures.forEach(tex => tex.dispose());
      geometry.dispose();
      material.dispose();
      accentGeo.dispose();
      accentMat.dispose();
    }
  };

  return rootGroup;
}
